frequency_ok.kernel_code:
pub fn frequency_ok(tdiff: u32) -> bool {
    tdiff != 0
}

password.kernel_code:
pub fn password(is_keep_marker: bool) -> Password {
    if is_keep_marker { Password::KeepStored } else { Password::Replace }
}

Password.kernel_code:
pub enum Password {
    /// `--keep--`: the stored password stays.
    KeepStored,
    /// A new password.
    Replace,
}

publish_ok.kernel_code:
pub fn publish_ok(num_samples: u32) -> bool {
    num_samples >= 1
}

stpm_ok.kernel_code:
pub fn stpm_ok(samples: u32) -> bool {
    samples >= 1
}
